"""Core implementations of BaM, GSM and gradient-based BBVI (ADVI / Score / Fisher).

All methods use a full-covariance Gaussian variational family and only require a
(JAX-differentiable) unnormalized log density `logp: R^D -> R`.
"""
import jax
import jax.numpy as jnp
import optax

jax.config.update("jax_enable_x64", True)


# ----------------------------------------------------------------------------- utils
def sym(A):
    return 0.5 * (A + A.T)


def sqrtm_psd(A):
    w, Q = jnp.linalg.eigh(sym(A))
    w = jnp.clip(w, 0.0, None)
    return (Q * jnp.sqrt(w)) @ Q.T


def sample_gauss(key, mu, cov, B):
    L = jnp.linalg.cholesky(sym(cov))
    eps = jax.random.normal(key, (B, mu.shape[0]))
    return mu + eps @ L.T


def gauss_kl(m0, S0, m1, S1):
    """KL(N(m0,S0) || N(m1,S1))."""
    D = m0.shape[0]
    L1 = jnp.linalg.cholesky(sym(S1))
    L0 = jnp.linalg.cholesky(sym(S0))
    M = jax.scipy.linalg.solve_triangular(L1, L0, lower=True)
    d = jax.scipy.linalg.solve_triangular(L1, m1 - m0, lower=True)
    ld1 = 2 * jnp.sum(jnp.log(jnp.diag(L1)))
    ld0 = 2 * jnp.sum(jnp.log(jnp.diag(L0)))
    return 0.5 * (jnp.sum(M ** 2) + jnp.sum(d ** 2) - D + ld1 - ld0)


def gauss_logpdf(z, mu, cov):
    D = mu.shape[0]
    L = jnp.linalg.cholesky(sym(cov))
    r = jax.scipy.linalg.solve_triangular(L, (z - mu).T, lower=True)
    return -0.5 * jnp.sum(r ** 2, 0) - jnp.sum(jnp.log(jnp.diag(L))) - 0.5 * D * jnp.log(2 * jnp.pi)


# ----------------------------------------------------------------------------- BaM
def bam_update(mu, cov, z, g, lam):
    """One closed-form batch-and-match update (Algorithm 1)."""
    B, D = z.shape
    zbar = z.mean(0)
    gbar = g.mean(0)
    zc = z - zbar
    gc = g - gbar
    C = zc.T @ zc / B
    Gam = gc.T @ gc / B
    U = lam * Gam + lam / (1 + lam) * jnp.outer(gbar, gbar)
    dm = mu - zbar
    V = cov + lam * C + lam / (1 + lam) * jnp.outer(dm, dm)
    # Sigma = 2 V (I + (I+4UV)^{1/2})^{-1}, computed in the equivalent symmetric form
    # Sigma = 2 V^{1/2} (I + (I + 4 V^{1/2} U V^{1/2})^{1/2})^{-1} V^{1/2}
    Vh = sqrtm_psd(V)
    M = sym(Vh @ U @ Vh)
    w, Q = jnp.linalg.eigh(M)
    w = jnp.clip(w, 0.0, None)
    inner = (Q * (2.0 / (1.0 + jnp.sqrt(1.0 + 4.0 * w)))) @ Q.T
    cov_new = sym(Vh @ inner @ Vh)
    mu_new = mu / (1 + lam) + lam / (1 + lam) * (cov_new @ gbar + zbar)
    return mu_new, cov_new


def make_bam(score, B, lam_fn):
    def step(state, key):
        mu, cov, t = state
        z = sample_gauss(key, mu, cov, B)
        g = jax.vmap(score)(z)
        mu, cov = bam_update(mu, cov, z, g, lam_fn(t))
        return (mu, cov, t + 1)

    def init(mu0, cov0):
        return (mu0, cov0, 0)

    return init, step, lambda s: (s[0], s[1])


# ----------------------------------------------------------------------------- GSM
def make_gsm(score, B):
    def step(state, key):
        mu, cov = state
        z = sample_gauss(key, mu, cov, B)
        s = jax.vmap(score)(z)

        def one(zb, sb):
            eps = cov @ sb - mu + zb
            dmz = mu - zb
            c = sb @ cov @ sb + (dmz @ sb) ** 2
            rho = 0.5 * (-1 + jnp.sqrt(1 + 4 * c))
            den = 1 + rho + dmz @ sb
            dmu = (eps - dmz * (sb @ eps) / den) / (1 + rho)
            mut = mu + dmu
            dS = jnp.outer(dmz, dmz) - jnp.outer(mut - zb, mut - zb)
            return dmu, dS

        dmu, dS = jax.vmap(one)(z, s)
        return (mu + dmu.mean(0), sym(cov + dS.mean(0)))

    def init(mu0, cov0):
        return (mu0, cov0)

    return init, step, lambda s: (s[0], s[1])


# ----------------------------------------------------------------------------- gradient-based
def _chol_from_params(p):
    Lr = p["L"]
    return jnp.tril(Lr, -1) + jnp.diag(jnp.exp(jnp.diag(Lr)))


def make_gradvi(logp, B, lr, loss="elbo"):
    """ADVI (loss='elbo'), score-based divergence ('score') or Fisher divergence ('fisher')
    minimized with Adam using the reparameterization trick (Algorithm 2)."""
    score = jax.grad(logp)
    opt = optax.adam(lr)

    def loss_fn(p, eps):
        L = _chol_from_params(p)
        z = p["mu"] + eps @ L.T
        if loss == "elbo":
            ent = jnp.sum(jnp.log(jnp.diag(L)))
            return -(jnp.mean(jax.vmap(logp)(z)) + ent)
        g = jax.vmap(score)(z)
        if loss == "score":
            # ||grad log q - grad log p||^2_Sigma = ||-eps - L^T g||^2
            r = eps + g @ L
            return jnp.mean(jnp.sum(r ** 2, 1))
        if loss == "fisher":
            # grad log q = -L^{-T} eps
            gq = jax.scipy.linalg.solve_triangular(L.T, eps.T, lower=False).T
            r = gq + g
            return jnp.mean(jnp.sum(r ** 2, 1))
        raise ValueError(loss)

    def step(state, key):
        p, os = state
        eps = jax.random.normal(key, (B, p["mu"].shape[0]))
        gr = jax.grad(loss_fn)(p, eps)
        upd, os = opt.update(gr, os, p)
        return (optax.apply_updates(p, upd), os)

    def init(mu0, cov0):
        L0 = jnp.linalg.cholesky(cov0)
        Lr = jnp.tril(L0, -1) + jnp.diag(jnp.log(jnp.diag(L0)))
        p = {"mu": mu0, "L": Lr}
        return (p, opt.init(p))

    def get(state):
        L = _chol_from_params(state[0])
        return state[0]["mu"], L @ L.T

    return init, step, get


# ----------------------------------------------------------------------------- runner
def run(method, mu0, cov0, key, n_checkpoints, every, metric_fn):
    """Runs `n_checkpoints * every` iterations; evaluates metric_fn(mu, cov, key)
    at iteration 0 and after every `every` iterations. Returns array (n_checkpoints+1, ...)."""
    init, step, get = method
    state = init(mu0, cov0)

    def inner(state, k):
        return step(state, k), None

    def outer(state, k):
        k1, k2 = jax.random.split(k)
        state, _ = jax.lax.scan(inner, state, jax.random.split(k1, every))
        mu, cov = get(state)
        return state, metric_fn(mu, cov, k2)

    k0, k1 = jax.random.split(key)
    m0 = metric_fn(*get(state), k0)
    _, ms = jax.lax.scan(outer, state, jax.random.split(k1, n_checkpoints))
    return jax.tree_util.tree_map(lambda a, b: jnp.concatenate([a[None], b], 0), m0, ms)


def make_method(name, logp, B, lr=None):
    score = jax.grad(logp)
    if name == "bam":
        return make_bam(score, B, lr)  # lr is lambda_t schedule function
    if name == "gsm":
        return make_gsm(score, B)
    if name in ("advi", "score", "fisher"):
        loss = "elbo" if name == "advi" else name
        return make_gradvi(logp, B, lr, loss)
    raise ValueError(name)
